create table if not exists public.funnel_event_types (event_type text primary key, description text not null, enabled boolean not null default true, created_at timestamptz not null default now()); insert into public.funnel_event_types(event_type,description) values ('page_view','Visualização de página'),('quiz_started','Início do quiz'),('quiz_answered','Resposta do quiz'),('lead_created','Lead criado'),('chat_started','Início do chat'),('chat_message','Mensagem no chat'),('checkout_started','Checkout iniciado'),('purchase','Compra aprovada'),('upsell','Upsell'),('refund','Reembolso'),('chargeback','Chargeback'),('checkout_abandoned','Checkout abandonado') on conflict (event_type) do nothing; alter table public.funnel_event_types enable row level security; revoke all on public.funnel_event_types from anon, authenticated; grant select on public.funnel_event_types to authenticated; drop policy if exists funnel_event_types_read on public.funnel_event_types; create policy funnel_event_types_read on public.funnel_event_types for select to authenticated using (enabled=true); create index if not exists integration_events_type_time_idx on public.integration_events (event_type, created_at desc);